mapper.select:
SELECT ass.model_id as modelId, COUNT(CASE WHEN am.severity = 'high' THEN 0 END) AS alertHigh, COUNT(CASE WHEN am.severity = 'medium' THEN 0 END) AS alertMedium, COUNT(CASE WHEN am.severity = 'low' THEN 0 END) AS alertLow FROM asset ass LEFT JOIN alert_message am ON ass.id = am.link_id WHERE am.type = 3 AND am.state = 1
/*是否只统计在库资产*/
AND ass.state = #{onlyInUse}
GROUP BY ass.model_id ORDER BY ass.model_id

SELECT ass.model_id AS modelId, COUNT(CASE WHEN assp.status = '1' THEN 0 END) AS pingActive, COUNT(CASE WHEN assp.status = '0' THEN 0 END) AS pingInactive FROM asset ass LEFT JOIN asset_ping assp ON ass.host = assp.host /*是否只统计在库资产*/
AND ass.state = #{onlyInUse}
GROUP BY ass.model_id ORDER BY ass.model_id

SELECT ass.idc_id AS idcId, COUNT(CASE WHEN am.severity = 'high' THEN 0 END) AS alertHigh, COUNT(CASE WHEN am.severity = 'medium' THEN 0 END) AS alertMedium, COUNT(CASE WHEN am.severity = 'low' THEN 0 END) AS alertLow FROM asset ass LEFT JOIN alert_message am ON ass.id = am.link_id WHERE am.type = 3 AND am.state = 1
/*是否只统计在库资产*/
AND ass.state = #{onlyInUse}
GROUP BY ass.idc_id ORDER BY ass.idc_id

SELECT ass.idc_id AS idcId, COUNT(CASE WHEN assp.status = '1' THEN 0 END) AS pingActive, COUNT(CASE WHEN assp.status = '0' THEN 0 END) AS pingInactive FROM asset ass LEFT JOIN asset_ping assp ON ass.host = assp.host /*是否只统计在库资产*/
AND ass.state = #{onlyInUse}
GROUP BY ass.idc_id ORDER BY ass.idc_id
